// Give every exported rule a nonempty meta.description explaining its
// constraint. Shared factories must return rule objects with the same metadata.
// The loader supplies resolved metadata after importing rule modules, allowing
// this check to cover descriptions generated by factories and template strings.

export default {
    meta: {
        type: 'suggestion',
        description: 'Give every ESLint rule a nonempty meta.description.',
        includeInReadme: true,
        schema: [],
        messages: {
            description: 'Add a nonempty meta.description explaining this rule\'s constraint. For factory-built rules, define the description on the returned rule object.',
        },
    },

    create(context) {
        return {
            Program(node) {
                const metadata = context.settings.workspaceRuleMetadata?.[context.filename];

                if (metadata && (typeof metadata.description !== 'string' || metadata.description.trim() === '')) {
                    context.report({ node: node, messageId: 'description' });
                }
            },
        };
    },
};
